const memberCount = $('Get Member Count').first().json;
const chatInfo = $('Get Chat Info').first().json;
const channelCount = $('Get Channel Subscribers').first().json;
const recentMessages = $('Get Recent Messages').first().json;
const adminsData = $('Get Admins').first().json;
const snapshotShaResponse = $('Get Snapshot SHA').first().json;

const groupMembers = memberCount?.result || 0;
const channelSubscribers = channelCount?.result || 0;

const admins = (adminsData?.result || []).map(a => ({
  name: [a.user.first_name, a.user.last_name].filter(Boolean).join(' '),
  username: a.user.username || null,
  status: a.status,
  isBot: a.user.is_bot
}));

const messages = (recentMessages?.result || []).map(u => u.message).filter(Boolean);

const keywords = {
  vpn: 0, resume: 0, ai: 0, reject: 0,
  visa: 0, interview: 0, salary: 0, job: 0
};

const keywordPatterns = {
  vpn: /vpn|فیلتر|شکن|proxy|تحریم/gi,
  resume: /resume|رزومه|cv|cover.?letter|کاور.?لتر/gi,
  ai: /ai|هوش.?مصنوعی|claude|chatgpt|cursor|gemini|machine.?learning/gi,
  reject: /reject|ریجکت|رد.?شد/gi,
  visa: /visa|ویزا|اقامت|مهاجرت/gi,
  interview: /interview|مصاحبه/gi,
  salary: /salary|حقوق|درآمد/gi,
  job: /job|استخدام|شغل|کار/gi
};

for (const msg of messages) {
  const text = msg.text || '';
  for (const [key, pattern] of Object.entries(keywordPatterns)) {
    const matches = text.match(pattern);
    if (matches) keywords[key] += matches.length;
  }
}

const topicMessages = {};
for (const msg of messages) {
  const threadId = msg.message_thread_id || 'general';
  if (!topicMessages[threadId]) topicMessages[threadId] = 0;
  topicMessages[threadId]++;
}

const now = new Date();
const snapshot = {
  timestamp: now.toISOString(),
  date: now.toISOString().split('T')[0],
  kpis: {
    groupMembers,
    channelSubscribers,
    crossPlatformReach: groupMembers + channelSubscribers,
    adminsCount: admins.filter(a => !a.isBot).length
  },
  keywords,
  topicActivity: topicMessages,
  admins,
  messagesSampled: messages.length,
  chatTitle: chatInfo?.result?.title || 'Tech Immigrants'
};

const snapshotSha = snapshotShaResponse?.sha || null;

return [{ json: { ...snapshot, _snapshotSha: snapshotSha } }];

