const snapshot = $('Transform & Aggregate').first().json;
const briefing = ($('AI Community Insights').first().json.output) || '';
const full = { ...snapshot, aiInsights: { generatedAt: new Date().toISOString(), briefing } };

// SHAs: snapshot-latest from 'Get Snapshot SHA', history file from 'Get History SHA' (both may 404).
const sha = full._snapshotSha || null;
let histSha = null;
try { const h = $('Get History SHA').first().json; if (h && h.sha) histSha = h.sha; } catch (e) {}

const clean = { ...full };
delete clean._snapshotSha;
const contentB64 = Buffer.from(JSON.stringify(clean, null, 2), 'utf8').toString('base64');

const latestBody = { message: 'chore: update community stats ' + clean.date, content: contentB64 };
if (sha) latestBody.sha = sha;
const historyBody = { message: 'chore: archive stats ' + clean.date, content: contentB64 };
if (histSha) historyBody.sha = histSha;

return [{ json: { ...full, _commitLatestBody: JSON.stringify(latestBody), _commitHistoryBody: JSON.stringify(historyBody) } }];
